CustomField.formula:
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__WideTotalCPCColorLineItem__c > 0 ,
TSGCFG__WideSumofCPCColor4__c / TSGCFG__WideTotalCPCColorLineItem__c,
IF( ABS(TSGCFG__WideTotalColor4Volume__c-TSGCFG__WideTotalVolumeIncludesColor4__c)<>0, TSGCFG__WideTotalColor4MonthlyCost__c / ABS(TSGCFG__WideTotalColor4Volume__c-TSGCFG__WideTotalVolumeIncludesColor4__c),
IF( TSGCFG__WideTotalCPCColorLineItem__c > 0, TSGCFG__WideSumofCPCColor4__c / TSGCFG__WideTotalCPCColorLineItem__c, 0
)
)
)
